    if inp != outp:
        print(f"Pair {i}: '{inp}' -> '{outp}'")
        # Look for patterns by comparing character by character
        shorter = min(len(inp), len(outp))
        pos = 0
        while pos < shorter and inp[pos] == outp[pos]:
            pos += 1

        if pos < shorter:
            # Found a difference
            if len(inp) < len(outp):
                # Insertion happened
                print(f"  Insertion at position {pos}: inserted '{outp[pos]}'")
            elif len(inp) > len(outp):
